/**
 * Resilience policies, the registry, and the runtime that code generated by the
 * annotation processor calls into. No dependencies besides the JSpecify annotations.
 */
@org.jspecify.annotations.NullMarked
module dev.resilience4cata.core {
    requires transitive org.jspecify;
    requires static dev.resilience4cata.annotations; // @Internal, @Experimental: CLASS retention, compile only

    exports dev.resilience4cata;
    exports dev.resilience4cata.event;
    exports dev.resilience4cata.generated;
}
